"use strict";(()=>{const data=window.LEARNWITHUS_LIFE_SKILLS||[],sel=document.getElementById('lifeQuizTopic'),root=document.getElementById('lifeQuizRoot');if(!data.length||!root)return;data.forEach(t=>sel.add(new Option(t.emoji+' '+t.name,t.id)));const params=new URLSearchParams(location.search),requested=params.get('topic')||'all';sel.value=[...sel.options].some(o=>o.value===requested)?requested:'all';const speak=t=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-IN';u.rate=.82;speechSynthesis.speak(u)},shuffle=a=>[...a].sort(()=>Math.random()-.5);let questions=[],i=0,score=0,current='all';function build(){current=sel.value;let pool=current==='all'?data.flatMap(t=>t.quiz.map(q=>({...q,topic:t.name}))):(data.find(t=>t.id===current)?.quiz||[]).map(q=>({...q,topic:data.find(t=>t.id===current)?.name}));questions=shuffle(pool).slice(0,10);i=0;score=0;round();history.replaceState({},'',location.pathname+'?topic='+current)}function finish(){const label=current==='all'?'All Life Skills':data.find(t=>t.id===current).name;root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / '+questions.length+'</p><p class="game-feedback">'+(score>=8?'Excellent life-skills learning!':'Good try. Review the learning cards and try again.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button id="again" class="practice-button journey-primary">Play again</button><a class="practice-button" href="life-skills.html'+(current==='all'?'':'?topic='+current)+'">📖 Review learning</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:questions.length,title:label+' Quiz',subtitle:score>=8?'Safe, kind and confident learning!':'Review and try again.',filename:'learnwithus-life-skills-score.svg',url:'life-skills-quiz.html?topic='+current});window.LearnWithUs?.recordQuiz?.(label+' quiz',score,questions.length,'life-skills-quiz.html?topic='+current);document.getElementById('again').onclick=build}function round(){if(i>=questions.length)return finish();const q=questions[i];root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(i+1)+' of '+questions.length+' · '+q.topic+'</p><p class="game-question">'+q.q+'</p><div class="game-options" id="opts"></div><p class="game-feedback" id="fb" role="status"></p><button id="next" class="practice-button game-next" hidden>'+(i===questions.length-1?'See score →':'Next →')+'</button></section>';const opts=document.getElementById('opts'),fb=document.getElementById('fb'),next=document.getElementById('next');shuffle(q.options).forEach(choice=>{const b=document.createElement('button');b.type='button';b.textContent=choice;b.onclick=()=>{const ok=choice===q.answer,msg=ok?'Correct answer! It is '+q.answer+'.':'Wrong answer. The correct answer is '+q.answer+'.';opts.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===q.answer)x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');if(ok)score++;fb.textContent=msg;speak(msg);next.hidden=false};opts.append(b)});next.onclick=()=>{i++;round()}}sel.addEventListener('change',build);build()})();